kubectl -n oracle patch innodbcluster mycluster --type=merge -p '{"spec":{"mycnf":"[mysqld]\nmax_connections=333\n"}}'; T2=$(date +%s); sleep 30; until [ "$(kubectl -n oracle get sts mycluster -o jsonpath={.status.updatedReplicas})" = 3 ] && [ "$(kubectl -n oracle get innodbcluster mycluster -o jsonpath={.status.cluster.status})" = ONLINE ]; do sleep 5; [ $(( $(date +%s)-T2 )) -gt 900 ] && break; done; echo ROLLED $(( $(date +%s)-T2 ))s; sql mycluster-0 mysql "select @@max_connections"
